begin;
alter table public.assessment_capability_grants drop constraint assessment_capability_grants_capability_check;
alter table public.assessment_capability_grants add constraint assessment_capability_grants_capability_check check(capability in('banks.read','items.write','items.approve','assessments.publish','exams.manage','grades.manage','grades.mark','grades.moderate','results.read','results.release','audit.read','team.manage','proctor.manage','proctor.observe','proctor.review'));
alter table public.assessment_capability_grants add column expires_at timestamptz,add column revoked_at timestamptz,add column revoked_by uuid references public.users(id),add column revision bigint not null default 1 check(revision>0);
create table public.assessment_staff_roles(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),title text not null check(length(title) between 1 and 200),created_by uuid not null references public.users(id),created_at timestamptz not null default clock_timestamp(),unique(tenant_id,id));
create table public.assessment_staff_role_versions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,role_id uuid not null,version integer not null check(version>0),title text not null,capabilities text[] not null check(cardinality(capabilities) between 1 and 11 and capabilities<@array['banks.read','items.write','items.approve','assessments.publish','exams.manage','grades.mark','grades.moderate','results.read','results.release','audit.read','team.manage']),created_by uuid not null references public.users(id),created_at timestamptz not null default clock_timestamp(),unique(tenant_id,id),unique(tenant_id,role_id,id),unique(role_id,version),foreign key(tenant_id,role_id) references public.assessment_staff_roles(tenant_id,id));
create table public.assessment_staff_role_assignments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,user_id uuid not null references public.users(id),role_id uuid not null,role_version_id uuid not null,expires_at timestamptz,revoked_at timestamptz,revoked_by uuid references public.users(id),revision bigint not null default 1 check(revision>0),created_by uuid not null references public.users(id),created_at timestamptz not null default clock_timestamp(),unique(tenant_id,id),foreign key(tenant_id,role_id,role_version_id) references public.assessment_staff_role_versions(tenant_id,role_id,id));
create unique index assessment_staff_role_current on public.assessment_staff_role_assignments(tenant_id,user_id,role_id) where revoked_at is null;
create table public.assessment_staff_commands(tenant_id uuid not null references public.tenants(id),actor_id uuid not null references public.users(id),idempotency_key text not null check(length(idempotency_key) between 8 and 200),request jsonb not null,result jsonb not null,created_at timestamptz not null default clock_timestamp(),primary key(tenant_id,actor_id,idempotency_key));
create trigger assessment_staff_versions_immutable before update or delete on public.assessment_staff_role_versions for each row execute function public.assessment_immutable();
create trigger assessment_staff_commands_immutable before update or delete on public.assessment_staff_commands for each row execute function public.assessment_immutable();
create function public.assessment_staff_assignment_guard() returns trigger language plpgsql set search_path=public,pg_temp as $$ begin if tg_op='DELETE' or row(new.id,new.tenant_id,new.user_id,new.role_id,new.role_version_id,new.expires_at,new.created_by,new.created_at) is distinct from row(old.id,old.tenant_id,old.user_id,old.role_id,old.role_version_id,old.expires_at,old.created_by,old.created_at) or old.revoked_at is not null or new.revoked_at is null or new.revoked_by is null or new.revision<>old.revision+1 then raise exception 'immutable_staff_assignment' using errcode='23514';end if;return new;end; $$;
create trigger assessment_staff_assignment_guard before update or delete on public.assessment_staff_role_assignments for each row execute function public.assessment_staff_assignment_guard();
create or replace function public.assessment_has_capability(p_tenant uuid,p_user uuid,p_capability text) returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select p_capability=any(array['banks.read','items.write','items.approve','assessments.publish','exams.manage','grades.manage','grades.mark','grades.moderate','results.read','results.release','audit.read','team.manage','proctor.manage','proctor.observe','proctor.review']) and exists(select 1 from public.tenant_memberships m where m.tenant_id=p_tenant and m.user_id=p_user and m.status='active' and (m.role in('owner','admin') or exists(select 1 from public.assessment_capability_grants g where g.tenant_id=p_tenant and g.user_id=p_user and g.capability=p_capability and g.revoked_at is null and (g.expires_at is null or g.expires_at>clock_timestamp())) or exists(select 1 from public.assessment_staff_role_assignments a join public.assessment_staff_role_versions v on v.id=a.role_version_id where a.tenant_id=p_tenant and a.user_id=p_user and a.revoked_at is null and (a.expires_at is null or a.expires_at>clock_timestamp()) and p_capability=any(v.capabilities))));
$$;
create or replace function public.assessment_staff_deadline(p_tenant uuid,p_actor uuid,p_capability text) returns timestamptz language sql stable security definer set search_path=public,pg_temp as $$
 with sources as(select g.expires_at expiry from public.assessment_capability_grants g where g.tenant_id=p_tenant and g.user_id=p_actor and g.capability=p_capability and g.revoked_at is null and (g.expires_at is null or g.expires_at>clock_timestamp()) union all select a.expires_at from public.assessment_staff_role_assignments a join public.assessment_staff_role_versions v on v.id=a.role_version_id where a.tenant_id=p_tenant and a.user_id=p_actor and a.revoked_at is null and (a.expires_at is null or a.expires_at>clock_timestamp()) and p_capability=any(v.capabilities))
 select case when exists(select 1 from public.tenant_memberships where tenant_id=p_tenant and user_id=p_actor and status='active' and role in('owner','admin')) or exists(select 1 from sources where expiry is null) then null else (select max(expiry) from sources) end;
$$;
create function public.assessment_staff_command(p_actor uuid,p_tenant uuid,p_key text,p_action text,p_data jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare request jsonb:=jsonb_build_object('action',p_action,'data',p_data);prior public.assessment_staff_commands;target uuid;role_record public.assessment_staff_roles;version_record public.assessment_staff_role_versions;assignment public.assessment_staff_role_assignments;grant_record public.assessment_capability_grants;caps text[];cap text;bootstrap boolean;deadline timestamptz;expiry timestamptz;expected bigint;result jsonb;rid uuid;new_version integer;
begin
 perform pg_advisory_xact_lock(hashtextextended('assessment.staff:'||p_tenant::text,0));
 target:=case when p_action='role.revoke' then (select user_id from public.assessment_staff_role_assignments where tenant_id=p_tenant and id=(p_data->>'assignment_id')::uuid) else (p_data->>'user_id')::uuid end;
 perform 1 from public.tenant_memberships where tenant_id=p_tenant and user_id=any(array[p_actor,target]) order by user_id for share;
 if not public.assessment_has_capability(p_tenant,p_actor,'team.manage') then raise exception 'forbidden' using errcode='42501';end if;
 if p_key is null or length(p_key) not between 8 and 200 or jsonb_typeof(p_data)<>'object' or length(coalesce(p_data->>'reason','')) not between 1 and 5000 then raise exception 'invalid_staff_command' using errcode='23514';end if;
 select * into prior from public.assessment_staff_commands where tenant_id=p_tenant and actor_id=p_actor and idempotency_key=p_key;if found then if prior.request<>request then raise exception 'idempotency_conflict' using errcode='23505';end if;return prior.result;end if;
 bootstrap:=exists(select 1 from public.tenant_memberships where tenant_id=p_tenant and user_id=p_actor and status='active' and role in('owner','admin'));
 if p_action in('capability.grant','capability.revoke','role.assign','role.revoke') then
  if target is null or not exists(select 1 from public.tenant_memberships where tenant_id=p_tenant and user_id=target) then raise exception 'member_not_found' using errcode='P0002';end if;
  if target=p_actor then raise exception 'self_permission_change' using errcode='42501';end if;
  if exists(select 1 from public.tenant_memberships where tenant_id=p_tenant and user_id=target and role in('owner','admin')) then raise exception 'organization_role_controls_access' using errcode='23514';end if;
  if p_action in('capability.grant','role.assign') and not exists(select 1 from public.tenant_memberships where tenant_id=p_tenant and user_id=target and status='active') then raise exception 'active_member_required' using errcode='23514';end if;
 end if;
 if p_action in('capability.grant','capability.revoke') then caps:=array[p_data->>'capability'];
 elsif p_action in('role.create','role.revise') then if jsonb_typeof(p_data->'capabilities')<>'array' then raise exception 'invalid_staff_role' using errcode='23514';end if;select array_agg(value order by value) into caps from jsonb_array_elements_text(p_data->'capabilities');
 elsif p_action='role.assign' then select * into version_record from public.assessment_staff_role_versions where tenant_id=p_tenant and id=(p_data->>'role_version_id')::uuid;if not found then raise exception 'role_not_found' using errcode='P0002';end if;caps:=version_record.capabilities;
 elsif p_action='role.revoke' then select * into assignment from public.assessment_staff_role_assignments where tenant_id=p_tenant and id=(p_data->>'assignment_id')::uuid for update;if not found then raise exception 'assignment_not_found' using errcode='P0002';end if;select * into version_record from public.assessment_staff_role_versions where id=assignment.role_version_id;caps:=version_record.capabilities;
 else raise exception 'unknown_staff_action' using errcode='22023';end if;
 if cardinality(caps) not between 1 and 11 or caps is null or cardinality(caps)<>(select count(distinct c) from unnest(caps)c) or not caps<@array['banks.read','items.write','items.approve','assessments.publish','exams.manage','grades.mark','grades.moderate','results.read','results.release','audit.read','team.manage'] then raise exception 'assessment_permissions_only' using errcode='23514';end if;
 expiry:=(p_data->>'expires_at')::timestamptz;if expiry is not null and expiry<=clock_timestamp() then raise exception 'future_expiry_required' using errcode='23514';end if;
 foreach cap in array caps loop
  if not bootstrap and (cap='team.manage' or not public.assessment_has_capability(p_tenant,p_actor,cap)) then raise exception 'delegation_exceeds_authority' using errcode='42501';end if;
  if not bootstrap and p_action in('capability.grant','role.assign') then deadline:=least(public.assessment_staff_deadline(p_tenant,p_actor,cap),public.assessment_staff_deadline(p_tenant,p_actor,'team.manage'));if deadline is not null and (expiry is null or expiry>deadline) then raise exception 'delegation_expiry_exceeds_authority' using errcode='23514';end if;end if;
 end loop;
 if p_action in('capability.grant','capability.revoke') then
  select * into grant_record from public.assessment_capability_grants where tenant_id=p_tenant and user_id=target and capability=caps[1] for update;
  expected:=(p_data->>'expected_revision')::bigint;if expected is null or expected<>coalesce(grant_record.revision,0) then raise exception 'permission_revision_conflict' using errcode='23505';end if;
  if p_action='capability.revoke' then if grant_record.capability is null then raise exception 'grant_not_found' using errcode='P0002';end if;update public.assessment_capability_grants set revoked_at=clock_timestamp(),revoked_by=p_actor,revision=revision+1 where tenant_id=p_tenant and user_id=target and capability=caps[1] returning * into grant_record;
  else insert into public.assessment_capability_grants(tenant_id,user_id,capability,granted_by,expires_at,revision) values(p_tenant,target,caps[1],p_actor,expiry,1) on conflict(tenant_id,user_id,capability) do update set granted_by=p_actor,created_at=clock_timestamp(),expires_at=excluded.expires_at,revoked_at=null,revoked_by=null,revision=assessment_capability_grants.revision+1 returning * into grant_record;end if;
  rid:=target;result:=jsonb_build_object('user_id',target,'capability',caps[1],'revision',grant_record.revision,'revoked',grant_record.revoked_at is not null);
 elsif p_action in('role.create','role.revise') then
  if length(coalesce(p_data->>'title','')) not between 1 and 200 then raise exception 'invalid_role_title' using errcode='23514';end if;
  if p_action='role.create' then insert into public.assessment_staff_roles(tenant_id,title,created_by) values(p_tenant,p_data->>'title',p_actor) returning * into role_record;new_version:=1;
  else select * into role_record from public.assessment_staff_roles where tenant_id=p_tenant and id=(p_data->>'role_id')::uuid for update;if not found then raise exception 'role_not_found' using errcode='P0002';end if;select max(version)+1 into new_version from public.assessment_staff_role_versions where role_id=role_record.id;if new_version-1<>(p_data->>'expected_version')::integer or p_data->>'expected_version' is null then raise exception 'role_revision_conflict' using errcode='23505';end if;end if;
  insert into public.assessment_staff_role_versions(tenant_id,role_id,version,title,capabilities,created_by) values(p_tenant,role_record.id,new_version,p_data->>'title',caps,p_actor) returning * into version_record;rid:=version_record.id;result:=jsonb_build_object('id',rid,'role_id',role_record.id,'version',new_version);
 elsif p_action='role.assign' then
  select * into assignment from public.assessment_staff_role_assignments where tenant_id=p_tenant and user_id=target and role_id=version_record.role_id and revoked_at is null for update;
  if assignment.id is distinct from (p_data->>'expected_assignment_id')::uuid then raise exception 'assignment_revision_conflict' using errcode='23505';end if;
  if assignment.id is not null then update public.assessment_staff_role_assignments set revoked_at=clock_timestamp(),revoked_by=p_actor,revision=revision+1 where id=assignment.id;end if;
  insert into public.assessment_staff_role_assignments(tenant_id,user_id,role_id,role_version_id,expires_at,created_by) values(p_tenant,target,version_record.role_id,version_record.id,expiry,p_actor) returning * into assignment;rid:=assignment.id;result:=jsonb_build_object('id',rid,'revision',assignment.revision);
 else if assignment.revoked_at is not null or assignment.revision<>(p_data->>'expected_revision')::bigint or p_data->>'expected_revision' is null then raise exception 'assignment_revision_conflict' using errcode='23505';end if;update public.assessment_staff_role_assignments set revoked_at=clock_timestamp(),revoked_by=p_actor,revision=revision+1 where id=assignment.id returning * into assignment;rid:=assignment.id;result:=jsonb_build_object('id',rid,'revision',assignment.revision);end if;
 insert into public.assessment_audit_events(tenant_id,actor_id,action,target_id,details) values(p_tenant,p_actor,'staff.'||p_action,rid,jsonb_build_object('user_id',target,'capabilities',caps,'reason',p_data->>'reason','result',result,'expires_at',expiry));
 insert into public.assessment_staff_commands(tenant_id,actor_id,idempotency_key,request,result) values(p_tenant,p_actor,p_key,request,result);return result;
end; $$;
create function public.assessment_staff_read(p_actor uuid,p_tenant uuid,p_kind text,p_id uuid default null,p_after uuid default null,p_limit integer default 100) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare result jsonb;bootstrap boolean;caps text[]:=array['banks.read','items.write','items.approve','assessments.publish','exams.manage','grades.mark','grades.moderate','results.read','results.release','audit.read','team.manage'];
begin
 bootstrap:=exists(select 1 from public.tenant_memberships where tenant_id=p_tenant and user_id=p_actor and status='active' and role in('owner','admin'));
 if p_kind='access' then return jsonb_build_object('can_manage',public.assessment_has_capability(p_tenant,p_actor,'team.manage'),'bootstrap',bootstrap,'delegable',(select coalesce(jsonb_agg(c),'[]'::jsonb) from unnest(caps)c where (c<>'team.manage' or bootstrap) and public.assessment_has_capability(p_tenant,p_actor,c)),'authority_ends_at',(select coalesce(jsonb_object_agg(c,least(public.assessment_staff_deadline(p_tenant,p_actor,c),public.assessment_staff_deadline(p_tenant,p_actor,'team.manage'))),'{}'::jsonb) from unnest(caps)c));end if;
 if not public.assessment_has_capability(p_tenant,p_actor,'team.manage') then raise exception 'forbidden' using errcode='42501';end if;if p_limit not between 1 and 100 or p_limit is null then raise exception 'invalid_page_limit' using errcode='22023';end if;
 if p_kind='members' then select coalesce(jsonb_agg(row),'[]'::jsonb) into result from(select jsonb_build_object('id',m.user_id,'status',m.status,'org_role',m.role,'inherited',m.role in('owner','admin'),'name',coalesce(nullif(coalesce(to_jsonb(u)->>'full_name',to_jsonb(u)->>'display_name',to_jsonb(u)->>'name',to_jsonb(u)->>'username'),''),'Member '||left(u.id::text,8))) row from (select distinct on(user_id) * from public.tenant_memberships where tenant_id=p_tenant and (p_after is null or user_id>p_after) order by user_id,(status='active') desc limit p_limit)m join public.users u on u.id=m.user_id) selected;return result;
 elsif p_kind='member' then if not exists(select 1 from public.tenant_memberships where tenant_id=p_tenant and user_id=p_id) then raise exception 'member_not_found' using errcode='P0002';end if;return jsonb_build_object('user_id',p_id,'grants',(select coalesce(jsonb_agg(jsonb_build_object('capability',g.capability,'revision',g.revision,'expires_at',g.expires_at,'revoked_at',g.revoked_at,'effective',public.assessment_has_capability(p_tenant,p_id,g.capability)) order by g.capability),'[]'::jsonb) from public.assessment_capability_grants g where g.tenant_id=p_tenant and g.user_id=p_id and g.capability=any(caps)),'roles',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'role_id',a.role_id,'role_version_id',v.id,'title',v.title,'version',v.version,'capabilities',v.capabilities,'revision',a.revision,'expires_at',a.expires_at,'revoked_at',a.revoked_at) order by a.created_at desc),'[]'::jsonb) from public.assessment_staff_role_assignments a join public.assessment_staff_role_versions v on v.id=a.role_version_id where a.tenant_id=p_tenant and a.user_id=p_id));
 elsif p_kind='roles' then select coalesce(jsonb_agg(to_jsonb(v)),'[]'::jsonb) into result from(select * from public.assessment_staff_role_versions where tenant_id=p_tenant and (p_after is null or id>p_after) order by id limit p_limit)v;return result;
 else raise exception 'unknown_resource' using errcode='22023';end if;
end; $$;
alter function public.assessment_grading_read(uuid,uuid,text,uuid,uuid,integer) rename to assessment_grading_read_v1;
create function public.assessment_grading_read(p_actor uuid,p_tenant uuid,p_kind text,p_id uuid default null,p_after uuid default null,p_limit integer default 100) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$ begin if p_kind='access' then return public.assessment_grading_read_v1(p_actor,p_tenant,p_kind,p_id,p_after,p_limit)||jsonb_build_object('can_manage_team',public.assessment_has_capability(p_tenant,p_actor,'team.manage'));end if;return public.assessment_grading_read_v1(p_actor,p_tenant,p_kind,p_id,p_after,p_limit);end; $$;
do $$ declare t text;begin foreach t in array array['assessment_staff_roles','assessment_staff_role_versions','assessment_staff_role_assignments','assessment_staff_commands'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end; $$;
revoke all on function public.assessment_staff_command(uuid,uuid,text,text,jsonb),public.assessment_staff_read(uuid,uuid,text,uuid,uuid,integer),public.assessment_staff_deadline(uuid,uuid,text),public.assessment_grading_read(uuid,uuid,text,uuid,uuid,integer) from public,anon,authenticated;
grant execute on function public.assessment_staff_command(uuid,uuid,text,text,jsonb),public.assessment_staff_read(uuid,uuid,text,uuid,uuid,integer),public.assessment_staff_deadline(uuid,uuid,text),public.assessment_grading_read(uuid,uuid,text,uuid,uuid,integer) to service_role;
commit;
